namespace YiKe.Translation;

public static partial class ProgrammingGlossary
{
    static Entry T(string title, string aliases, string meaning, bool technical = false, string[]? symbols = null, bool caseSensitive = false) => new(title, aliases, meaning, ignoreCase: !caseSensitive, technical: technical, symbols: symbols);
    static Entry Cmd(string title, string aliases, string meaning, bool technical = true) => new(title, aliases, "Linux / Unix：" + meaning + "\n这里只解释所选文字，不执行命令。", technical: technical, command: true);
    static readonly Entry[] ComputerEntries =
    {
        T("Linux · 操作系统内核", "Linux|GNU/Linux", "Linux 严格说是内核；常见发行版还包含用户空间工具、库和软件管理体系。发行版、内核版本与命令实现不同，选项可能有差异。", true),
        T("Unix / POSIX · 系统与接口标准", "Unix|POSIX", "Unix 是一类操作系统及其传统；POSIX 规定可移植操作系统接口。Linux 的许多接口遵循 Unix / POSIX 习惯，但不能假设所有扩展在其他系统上都可用。", true),
        T("distribution · 发行版", "distribution|distro|发行版", "Linux 发行版将内核、工具、软件包和默认配置组合成可安装系统，例如 Debian、Ubuntu、Fedora；发行版不是单独的内核版本。"),
        T("shell / Bash · 命令解释器", "shell|Bash|zsh|命令解释器", "shell 解析命令、展开变量并组织管道和重定向；Bash、zsh 是具体实现。终端提供输入输出界面，shell 负责解释，不是同一组件。", true),
        T("terminal / TTY · 终端", "terminal|TTY|PTY|终端|伪终端", "终端提供程序的交互输入输出；PTY 是伪终端接口，终端模拟器、SSH 等可使用它。终端中运行的 shell 与终端窗口本身不同。"),
        Cmd("ls · 列目录", "ls", "列出文件信息；-l 显示详细格式，-a 包含点开头的隐藏项，-h 在支持的格式中使用易读大小。-la 常表示合并两个短选项。"),
        Cmd("cd / pwd · 当前目录", "cd|pwd", "cd 是常见 shell 内建命令，用于改变当前 shell 的目录；cd .. 到上级目录，cd ~ 到家目录。pwd 输出当前工作目录。"),
        Cmd("mkdir / rmdir · 建立与删除目录", "mkdir|rmdir", "mkdir 建目录；-p 按需创建父目录。rmdir 通常只删除空目录，不等于 rm -r 的递归删除。"),
        Cmd("cp / mv · 复制与移动", "cp|mv", "cp 复制文件，复制目录通常用 -r / -R；mv 移动或改名。目标已存在时可能覆盖，确切行为受选项、别名和实现影响。"),
        Cmd("rm · 删除目录项", "rm", "移除文件名；-r / -R 递归处理目录，-f 通常跳过不存在文件并不询问。rm -rf 可能直接删除整棵目录，通常不进入回收站；最终数据释放还取决于硬链接和打开的文件。"),
        Cmd("cat · 输出文件", "cat", "按顺序将文件内容写到标准输出，也可连接多个文件；文件名本身不是命令选项的解释。", false),
        Cmd("less / head / tail · 阅读文本", "less|head|tail", "less 分页阅读；head / tail 默认查看开头 / 末尾部分。tail -f 持续跟踪追加内容，tail -F 还常用于跟踪被轮转替换的文件名。", false),
        Cmd("grep · 按模式筛选行", "grep|rg|ripgrep", "grep 搜索匹配模式的行；-n 输出行号，-i 忽略大小写，-r 递归目录，-E 使用扩展正则。rg 是 ripgrep 工具，默认行为与 grep 不完全相同。"),
        Cmd("find · 按属性查找文件", "find", "从指定路径遍历文件树，以 -name、-type 等条件筛选；-name 常用 shell 风格通配模式，不是普通正则。-delete 或 -exec 可产生修改，不能当作纯搜索参数。", false),
        Cmd("sed / awk · 文本处理", "sed|awk", "sed 常用于按规则编辑文本流；-n 可抑制默认输出，-i 的原地编辑形式因实现而异。awk 按记录和字段执行模式 / 动作规则，常用于提取与汇总。"),
        Cmd("sort / uniq / wc · 排序与计数", "sort|uniq|wc", "sort 排序；uniq 默认只合并相邻重复行，常与排序配合；wc 可按行、单词、字节或字符计数，选项决定统计对象。", false),
        Cmd("touch / file / stat · 文件元信息", "touch|file|stat", "touch 修改时间戳，文件不存在时通常创建空文件；file 判断内容类型；stat 显示 inode 等元数据，不等于读取完整文件内容。", false),
        Cmd("ln · 建立链接", "ln", "默认建立硬链接；ln -s 建立符号链接。硬链接指向同一文件对象，符号链接保存路径，目标移走后可能失效。"),
        Cmd("chmod · 修改权限位", "chmod", "改变文件模式位。常见八进制位 r=4、w=2、x=1；755 为所有者 rwx、组和其他人 r-x，644 为 rw- / r-- / r--。-R 递归，不应一律给所有文件 777。"),
        Cmd("chown / chgrp · 改所有者与组", "chown|chgrp", "chown 修改所有者并可指定组；chgrp 修改所属组。-R 可递归；修改通常需要相应权限，符号链接处理还取决于选项和实现。"),
        Cmd("sudo / su · 切换执行身份", "sudo|su", "sudo 按策略以其他身份运行命令，常见目标为 root；su 切换用户身份或启动对应 shell。拥有 sudo 命令不代表当前用户可执行任意特权操作。"),
        T("root / UID / GID · 用户身份", "root|UID|GID|超级用户|用户标识", "root 用户通常对应 UID 0；UID 标识用户，GID 标识组。root 也可指文件系统根目录 /，需看语境；能力机制、命名空间和安全策略仍可限制操作。"),
        T("rwx / umask · 权限与默认屏蔽", "rwx|umask|权限位", "r / w / x 分别表示读、写、执行；对目录，x 是遍历，w 关系到目录项修改。umask 屏蔽新建对象的默认权限位，不是简单的十进制减法。", true),
        Cmd("ps / top / htop · 查看进程", "ps aux|ps|top|htop", "ps 输出进程快照；top / htop 持续显示资源使用。ps aux 与 ps -ef 属于不同选项风格；CPU、内存与负载是不同指标。", false),
        Cmd("kill / pkill · 发送信号", "kill|pkill", "向进程发送信号，不只用于杀进程。常见默认是 SIGTERM，允许程序处理退出；SIGKILL（常见编号 9）不可捕获，无法让程序正常清理。", false),
        T("SIGTERM / SIGKILL / SIGINT · 信号", "SIGTERM|SIGKILL|SIGINT|SIGSTOP|SIGHUP", "Linux 信号用于通知进程事件。SIGTERM 请求终止；SIGINT 常来自终端 Ctrl+C；SIGKILL 强制终止、SIGSTOP 停止执行，后两者不能被捕获或忽略。SIGHUP 的具体处理由程序决定。", true),
        Cmd("systemctl · 管理 systemd 单元", "systemctl", "start / stop / restart 控制当前运行；enable / disable 控制随目标启动的关系，enable 通常不等于立即 start。status 查看状态，--user 管理用户实例。"),
        Cmd("journalctl · 查看日志", "journalctl", "读取 systemd journal；-u 按单元筛选，-f 跟踪新增日志，-b 选择一次启动的记录。能否读取日志取决于权限和日志保存配置。"),
        T("systemd / daemon · 服务管理", "systemd|daemon|守护进程", "daemon 是通常在后台长期运行的服务进程；systemd 是 Linux 上常见的系统 / 服务管理器，以 unit 管理服务、挂载点、定时器等，并非所有发行版都采用它。", true),
        Cmd("apt / apt-get · Debian 系软件包管理", "apt|apt-get", "update 更新软件包索引；upgrade 升级已安装软件包；install / remove 安装和移除。更新索引本身不会把全部已安装软件升级，apt 的交互界面不等于稳定脚本接口。"),
        Cmd("dnf / yum / pacman · 软件包管理", "dnf|yum|pacman", "dnf / yum 常见于 RPM 系发行版；pacman 常见于 Arch。命令和仓库机制不同，不应把 apt 的子命令或选项直接套用。"),
        Cmd("dpkg / rpm · 软件包工具", "dpkg|rpm", "处理具体软件包的安装、查询等低层操作；与 apt / dnf 这类仓库和依赖管理前端并不完全相同，单装一个包不保证依赖已全部满足。"),
        Cmd("tar / gzip / unzip · 归档与压缩", "tar|gzip|gunzip|unzip|zip", "tar 打包文件，压缩由具体选项或外部算法决定；常见 tar -xzf 中 x=解包、z=gzip、f=后接归档文件名。解包会写文件，归档与压缩不是同一概念。"),
        Cmd("df / du · 空间统计", "df|du", "df 报告文件系统的容量使用，du 统计目录树中的文件占用；已删除但仍打开的文件、稀疏文件、快照等会使两者结果不同。-h 常以易读单位显示。"),
        Cmd("free / vmstat · 内存与系统活动", "free|vmstat", "free 显示内存与交换区统计；available 通常比只看 free 更能反映可供应用使用的内存。vmstat 展示内存、调度、I/O 等活动，不只统计虚拟内存大小。", false),
        Cmd("mount / umount · 挂载文件系统", "mount|umount", "mount 将文件系统接到目录树的挂载点；umount 卸载。挂载不等于格式化；设备仍被进程使用时卸载可能失败。", false),
        Cmd("lsblk / blkid / fdisk · 块设备信息", "lsblk|blkid|fdisk", "lsblk 查看块设备拓扑，blkid 查询文件系统标识；fdisk 可查看或修改分区表。分区、文件系统和挂载点是不同层次，修改分区表可能破坏数据。"),
        Cmd("dd / mkfs · 低层写入与格式化", "dd|mkfs", "dd 按输入 / 输出复制数据，if= 指输入、of= 指输出；mkfs 创建文件系统。目标设备选错可覆盖已有数据，不能把命令解释当作执行授权。"),
        Cmd("ip / ss · 网络配置与套接字", "ip|ss", "ip 查看或配置地址、路由和链路；ss 查看套接字状态，-l 常表示监听、-n 显示数值、-t 选 TCP、-u 选 UDP。端口不等于进程标识。"),
        Cmd("ping / traceroute · 网络诊断", "ping|traceroute|tracepath", "ping 常用 ICMP 探测可达性和往返时间；traceroute / tracepath 探索路径。对方或中间设备可能过滤探测，探测失败不能单独证明目标服务已离线。"),
        Cmd("curl / wget · 请求与下载", "curl|wget", "curl 支持多种协议；-I 请求 HTTP 响应头，-L 跟随重定向，-o 写指定文件。wget 常用于下载；不同工具的大小写选项可能有完全不同含义。"),
        Cmd("ssh / scp / sftp · 安全远程访问", "ssh|scp|sftp", "ssh 建立加密的远程登录或转发；scp / sftp 传输文件。服务器主机密钥用于确认远端身份，用户密钥用于用户认证，二者不同。"),
        Cmd("rsync · 增量同步", "rsync", "比较源和目标并传输差异；-a 是归档模式的一组选项，-n 可预演。源路径末尾的 / 会影响复制层次；--delete 还会移除目标中源端没有的项。"),
        Cmd("export / env / PATH · 环境变量", "export|env|PATH", "export 将 shell 变量导出给后续子进程，env 查看或指定程序环境。PATH 是搜索可执行文件的目录列表；改变子进程环境通常不会反向修改父进程。"),
        Cmd("man / --help · 本机帮助", "man|--help", "man 阅读手册；章节号区分命令、系统调用、库函数等。--help 常显示工具选项摘要；准确含义应以目标机器上的实际实现和版本为准。", false),
        Cmd("cron / crontab · 定时任务", "cron|crontab", "cron 根据时间规则调度任务；crontab 管理对应任务表。任务的环境、工作目录和可用 PATH 可能与交互 shell 不同。"),
        Cmd("nohup / jobs / bg / fg · 作业控制", "nohup|jobs|bg|fg", "jobs 查看当前 shell 作业，bg / fg 改变后台 / 前台运行。nohup 通常使命令忽略挂断信号，但不自动提供完整服务管理，也不必然自行转入后台。"),
        Cmd("xargs / tee · 组合命令", "xargs|tee", "xargs 将输入转换为命令参数；含空格或换行的文件名需正确分隔，常见配合 -0。tee 把输入同时写到标准输出和文件，-a 常表示追加。"),
        Cmd("strace / lsof / dmesg · 系统诊断", "strace|lsof|dmesg", "strace 观察系统调用与信号，lsof 查看打开的文件和套接字，dmesg 阅读内核消息。访问权限和工具选项会影响可见范围。"),
        Cmd("uname / hostname / whoami / id · 系统与身份", "uname|hostname|hostnamectl|whoami|id", "uname 显示内核等系统信息，hostname / hostnamectl 查看或设置主机名；whoami 显示当前有效用户名称，id 显示用户和组标识。内核版本不等于发行版版本。", false),
        Cmd("echo / printf / read · shell 输入输出", "echo|printf|read", "echo 输出参数，但转义和选项行为因实现而异；printf 按格式字符串输出，read 常为 shell 内建读取输入。外部数据应作为参数而非不受控格式字符串。", false),
        Cmd("source / alias · shell 环境", "source|alias", "source（或 .）在当前 shell 环境中读取执行脚本；另启动一个 shell 通常不会修改父 shell。alias 定义命令别名，可能改变交互命令的实际行为。", false),
        Cmd("test / [ / [[ · 条件判断", "test|[[", "test 和 [ 常用于字符串、数字、文件条件判断；[ 需要匹配独立参数 ]。Bash 的 [[ 是扩展条件语法，不能假设所有 POSIX shell 都支持。", false),
        Cmd("netstat / ifconfig · 网络工具", "netstat|ifconfig", "netstat 查看连接、路由等信息，ifconfig 查看或配置网络接口；在许多 Linux 环境中也常使用 ip 与 ss。输出与选项依工具实现而定。"),
        Cmd("vim / nano · 终端编辑器", "vim|vi|nano", "用于在终端编辑文件；Vim 有普通、插入等模式，按键含义随模式变化。打开编辑器并不等于保存文件，保存位置和退出操作应以实际界面为准。"),
        T("| / > / >> / 2>&1 · shell 数据流", "2>&1|>>|>|管道符|重定向符", "常见 shell 中 | 连接 stdout 与下一命令 stdin；> 通常覆盖写文件，>> 追加，2>&1 将 stderr 复制到当时 stdout 的去向。编程语言中的 > 还可能是比较，| 可能是按位或，需结合语境。", symbols: new[] { "|" }),
        T("&& / || · 条件执行与短路", "&&", "常见 shell 中，前一命令成功才执行 && 后的命令，失败才执行 || 后的命令；许多编程语言中它们表达短路逻辑运算。shell 按退出状态判断，常见成功值为 0，不能直接套用所有语言的真值规则。", symbols: new[] { "||" }),
        T("stdin / stdout / stderr · 标准流", "stdin|stdout|stderr|标准输入|标准输出|标准错误", "Unix 进程通常有标准输入、输出、错误流，常见文件描述符为 0、1、2。错误流与输出流可分别重定向，不能假定所有错误文字都写在 stdout。", true),
        T("pipe / redirection · 管道与重定向", "pipe|pipeline|redirection|管道|重定向", "shell 中 | 常把前一命令 stdout 接到后一命令 stdin；> 常覆盖输出文件，>> 追加，2> 指定 stderr。2>&1 等重定向按顺序处理，交换顺序可能改变结果。"),
        T("file descriptor · 文件描述符", "file descriptor|文件描述符", "进程内用于引用打开文件描述的整数标识，也可用于管道和套接字。文件描述符不同于文件路径；复制描述符可能共享偏移和状态。", true),
        T("inode / hard link / symlink · 文件对象与链接", "inode|hard link|symbolic link|symlink|硬链接|符号链接|软链接", "inode 保存文件对象元数据等信息，目录项把名字关联到它；硬链接关联同一对象，符号链接保存路径。文件名不属于 inode 自身，硬链接通常不能跨文件系统。", true),
        T("filesystem / ext4 / XFS · 文件系统", "filesystem|file system|ext4|XFS|Btrfs|文件系统", "文件系统组织文件、目录和元数据；ext4、XFS、Btrfs 是不同实现，日志、快照和校验等能力并不相同。分区、卷和文件系统不应混为一谈。", true),
        T("/proc / /sys / /dev · 系统接口目录", "/proc|/sys|/dev|/etc|/var|/home|/tmp", "/proc、/sys 常以伪文件形式暴露进程、内核和设备信息；/dev 包含设备节点。/etc 常放系统配置，/var 放可变数据，/home 是常见用户家目录，/tmp 存临时文件，具体布局依系统而定。", true),
        T("kernel / user space · 内核与用户空间", "kernel|user space|kernel space|内核|用户空间|内核空间", "内核管理处理器、内存、设备和权限；应用主要在用户空间运行，通过系统调用请求受控服务。内核态与用户态的切换不等于进程切换。", true),
        T("process / PID · 进程", "process|processes|PID|进程", "进程是运行程序及其资源的实例，通常拥有独立虚拟地址空间；PID 是进程标识且可能被系统重用。一个进程可包含多个线程。"),
        T("thread · 线程", "thread|threads|线程", "线程是执行流，常与同一进程中的线程共享地址空间和部分资源；并发访问共享可变状态需要同步。线程数增加不保证程序更快。"),
        T("system call / syscall · 系统调用", "system call|syscall|系统调用", "用户程序通过受控入口请求内核功能，例如文件 I/O、进程创建和内存映射；普通库函数不一定对应一次系统调用。", true),
        T("fork / exec / wait · 进程生命周期", "fork|exec|waitpid", "Unix 中 fork 创建子进程；exec 系列以新程序替换当前进程映像，通常不新建 PID；wait / waitpid 用于等待和回收子进程状态。", true),
        T("zombie / orphan · 僵尸与孤儿进程", "zombie|orphan process|僵尸进程|孤儿进程", "僵尸进程已退出但退出状态尚未被回收，不再执行普通用户代码；孤儿进程的父进程已退出，会被其他适当进程接管。两者不是同一状态。", true),
        T("segmentation fault / SIGSEGV · 段错误", "segmentation fault|SIGSEGV|段错误", "进程访问了不允许访问的内存，Linux 通常发送 SIGSEGV；默认动作可使该进程终止并产生核心转储（受配置限制）。这不是整个操作系统必然崩溃，常见根因包括无效指针和越界访问。", true),
        T("IPC · 进程间通信", "IPC|inter-process communication|进程间通信", "进程间交换数据和通知的机制，包括管道、套接字、共享内存、消息队列和信号等；共享内存本身不自动解决并发同步。", true),
        T("mutex / semaphore · 互斥与计数同步", "mutex|semaphore|互斥锁|信号量", "互斥锁常用于保护临界区的独占访问；信号量维护计数，可限制并发资源数或通知事件。具体所有权、唤醒与公平性规则取决于实现。", true),
        T("deadlock · 死锁", "deadlock|死锁", "多个执行单元相互等待对方持有的资源，导致无法推进。避免环形等待、统一锁顺序和缩小持锁范围是常见处理思路，超时本身不保证根因消失。", true),
        T("race condition / data race · 竞态", "race condition|data race|竞态条件|数据竞争", "竞态条件是正确性依赖事件先后顺序；数据竞争通常涉及未充分同步的并发内存访问且至少一方写入。语言内存模型可能赋予数据竞争不同后果。", true),
        T("atomic / memory barrier · 原子与内存序", "atomic|memory barrier|memory ordering|原子操作|内存屏障|内存序", "原子操作对目标访问提供不可分割性；内存序 / 屏障约束可见性和重排序。原子变量并不自动使由多个步骤组成的算法整体正确或无锁。", true),
        T("context switch / scheduler · 调度", "context switch|scheduler|上下文切换|调度器", "调度器选择可运行任务；上下文切换保存和恢复执行状态，可能伴随缓存开销。异步任务、线程和进程之间的切换成本与机制不同。", true),
        T("virtual memory / paging · 虚拟内存", "virtual memory|paging|page table|虚拟内存|分页|页表", "虚拟地址经页表等机制映射到物理页，提供隔离、共享与按需分配。虚拟内存不等于交换分区；虚拟地址空间大小也不等于实际物理内存占用。", true),
        T("copy-on-write / COW · 写时复制", "copy-on-write|copy on write|COW|写时复制", "先共享可读取的数据，仅在需要修改时才建立相应私有副本。Linux fork 后，父子进程可先共享物理页，在首次写入相关页时按需复制；并非每次赋值都复制整个进程，也不表示父子进程的修改会自动互相同步。", true, caseSensitive: true),
        T("page fault / swap / OOM · 内存状态", "page fault|swap|OOM|OOM killer|缺页|交换空间", "缺页异常可能只是按需建立映射，也可能需要 I/O，不一定是程序错误。swap 可存放部分换出内存；OOM 表示内存分配压力达到无法满足的程度，系统可能终止进程。", true),
        T("mmap / shared memory · 内存映射", "mmap|shared memory|内存映射|共享内存", "mmap 将文件或匿名区域映射到进程地址空间；共享映射可用于进程间共享数据。可见性、同步、写回和生命周期仍由映射方式与相关接口决定。", true),
        T("cgroups / namespaces · 资源限制与隔离", "cgroup|cgroups|namespaces|命名空间隔离", "Linux cgroups 组织进程并控制 / 统计资源；namespaces 隔离进程看到的部分系统视图，如 PID、网络和挂载。它们是容器的基础机制，但不等于完整虚拟机。", true),
        T("epoll / select / poll · I/O 多路复用", "epoll|select|poll|I/O multiplexing|多路复用", "让一个线程等待多个 I/O 对象的就绪通知；Linux epoll 使用关注集合与事件接口。就绪通知不代表所有后续操作都必然完成，边沿与水平触发的处理方式也不同。"),
        T("TCP · 可靠字节流", "TCP|Transmission Control Protocol", "面向连接的传输协议，提供有序可靠字节流及流量 / 拥塞控制；应用消息边界需自行定义。可靠传输不代表应用业务一定成功或永不超时。", true),
        T("UDP · 数据报", "UDP|User Datagram Protocol", "提供数据报传输，本身不保证到达、顺序或去重；应用可自行构建可靠机制。常用于实时通信等场景，不应简单理解为必然比 TCP 更快。", true),
        T("IP / IPv4 / IPv6 · 网络层地址", "IP|IPv4|IPv6|IP address|IP地址", "IP 用于寻址与路由；IPv4 地址为 32 位，IPv6 为 128 位。地址不等于端口，也不一定永久对应某台机器；地址和域名是不同概念。", true),
        T("CIDR / subnet / gateway · 子网与路由", "CIDR|subnet|gateway|子网|网关", "CIDR 用前缀长度描述地址块，例如 IPv4 /24 指前 24 位为网络前缀；网关是到其他网络的下一跳之一。是否同网段应按地址和前缀判断。", true),
        T("DNS · 域名系统", "DNS|Domain Name System|域名解析", "分布式名称系统，常将域名解析为 IP，也支持 MX、TXT 等其他记录。缓存与 TTL 影响更新传播；DNS 查询成功不代表应用服务可用。", true),
        T("DHCP / NAT · 地址分配与转换", "DHCP|NAT|地址转换", "DHCP 自动分配地址等网络参数；NAT 改写通信中的地址或端口映射。NAT 与防火墙职责不同，公网地址也不代表所有端口都可达。", true),
        T("ARP / ICMP · 链路解析与控制消息", "ARP|ICMP", "IPv4 的 ARP 常在本地链路解析下一跳硬件地址；ICMP 传递网络控制和错误消息，ping 常使用它。IPv6 的邻居发现不直接使用 ARP。", true),
        T("socket / port · 套接字与端口", "socket|sockets|port|套接字|端口", "套接字是通信端点接口；传输层端口标识服务端点的一部分。TCP / UDP 的端口空间不同，监听地址、协议和端口共同决定可连接范围。"),
        T("HTTP / HTTPS · Web 协议", "HTTP|HTTPS", "HTTP 定义请求、响应、方法和状态等语义；HTTPS 通常是在 TLS 保护的连接上传输 HTTP。HTTPS 加密传输不等于网站内容或业务行为一定可信。", true),
        new("GET / POST / PUT / DELETE · HTTP 方法", "GET|POST|PUT|DELETE|PATCH|HEAD|OPTIONS", "HTTP 方法表达请求意图；GET 常读取表示，POST 提交处理，PUT 按目标替换，PATCH 局部修改，DELETE 请求移除。幂等性指预期服务端效果，不保证每次响应完全相同。"),
        T("HTTP status · 响应状态", "404|401|403|429|500|502|503|504|状态码", "常见 HTTP 状态：401 需认证，403 拒绝访问，404 未找到，429 请求过多；500 服务端内部错误，502 网关响应异常，503 暂不可用，504 网关超时。还需结合实际协议和服务上下文。"),
        T("TLS / certificate · 传输加密与证书", "TLS|SSL|X.509|传输层安全|数字证书", "TLS 提供传输机密性、完整性和认证；证书将身份与公钥关联，需核对信任链、名称和有效期等。自签名文件有签名不表示默认受系统信任；SSL 是历史协议名称。", true),
        T("proxy / reverse proxy · 代理", "reverse proxy|forward proxy|proxy|反向代理|正向代理", "正向代理通常代表客户端访问目标；反向代理通常代表后端接收请求，可用于路由、TLS 终止和负载分担。代理与 VPN 的工作层次和覆盖范围不同。"),
        T("CDN / load balancer · 内容分发与负载均衡", "CDN|load balancer|load balancing|负载均衡|内容分发网络", "CDN 将内容或接入节点部署到多地；负载均衡把流量分配到多个实例。缓存一致性、会话保持和健康检查需按应用设计，并非加一层就自动消除故障。", true),
        T("WebSocket / SSE · 持续通信", "WebSocket|SSE|Server-Sent Events", "WebSocket 提供持久双向消息通信；SSE 通过 HTTP 文本事件流向客户端推送，常为单向。二者的协议、重连和代理缓冲行为不同。", true),
        T("REST / RPC / gRPC · 接口风格", "REST|RPC|gRPC", "REST 是围绕资源与统一接口的架构风格；RPC 以远程过程调用为模型。gRPC 是具体 RPC 框架，常使用 Protocol Buffers 与 HTTP/2，不等同于所有 RPC。", true, caseSensitive: true),
        T("CORS / cookie / session · 浏览器访问状态", "CORS|cookie|session|同源策略|跨域", "CORS 是浏览器对跨源读取的许可机制，不是通用服务端认证。cookie 是浏览器保存并按规则发送的数据；session 常指服务端或应用维持的会话状态，二者不等同。", true),
        T("URL / URI / endpoint · 资源定位", "URL|URI|endpoint|端点", "URI 标识资源，URL 通常还描述定位方式；endpoint 是服务的访问入口。主机、路径、查询参数和片段职责不同，片段通常不作为 HTTP 请求目标发送。", true),
        T("bandwidth / latency / throughput · 网络性能", "bandwidth|latency|throughput|带宽|延迟|吞吐量", "带宽描述容量，吞吐量是实际单位时间处理量，延迟是一次操作的等待时间。高带宽不必然低延迟；排队、丢包、处理时间等都会影响体验。"),
        T("firewall / VPN · 网络访问控制", "firewall|VPN|防火墙|虚拟专用网络", "防火墙按策略过滤流量；VPN 在网络间建立受保护的逻辑通道。允许通过防火墙不等于应用已监听，连接 VPN 也不自动保证所有流量或终端安全。", true),
        T("SQL / relational database · 关系数据库", "SQL|RDBMS|relational database|关系数据库|结构化查询语言", "关系数据库以表、约束和关系运算管理数据，SQL 是常用操作语言。不同数据库的方言、事务、类型和执行计划存在差异。", true),
        new("SELECT / JOIN / GROUP BY · SQL 查询", "SELECT|JOIN|GROUP BY|ORDER BY|WHERE|HAVING", "SELECT 指定查询输出，WHERE 筛选行，JOIN 连接数据；GROUP BY 分组，HAVING 筛选组，ORDER BY 排序。具体结果和优化不能仅按源码中各词出现顺序推断。"),
        T("primary key / foreign key · 键与约束", "primary key|foreign key|主键|外键", "主键唯一标识行，通常要求唯一且非空；外键维护引用关系，约束相关行的存在或变化。外键不等于自动创建所有有用索引，行为依数据库实现。", true),
        T("index / B-tree · 数据库索引", "B-tree|B+ tree|B+tree|database index|数据库索引|B树|B+树", "索引是加速特定访问路径的数据结构，B 树及其变体适合有序和范围查询。索引占空间并增加写入维护成本，是否使用取决于查询与优化器。", true),
        T("transaction / ACID · 事务", "transaction|ACID|事务", "事务把一组操作作为受控整体；ACID 指原子性、一致性、隔离性、持久性。隔离级别和应用约束仍影响并发结果，事务不等于任意业务都自动正确。", true),
        T("MVCC / isolation level · 并发隔离", "MVCC|isolation level|隔离级别|多版本并发控制", "MVCC 利用数据版本实现并发访问；隔离级别决定可观察到哪些并发现象。读已提交、可重复读、可串行化等在不同数据库中细节不同，不能只凭名称假定实现一致。", true),
        T("dirty read / phantom read · 读取异常", "dirty read|phantom read|nonrepeatable read|脏读|幻读|不可重复读", "脏读读取其他事务尚未提交的数据；不可重复读涉及同一行前后不同；幻读涉及同一条件查询的行集合改变。能否发生取决于隔离级别与具体实现。", true),
        T("WAL / replication / sharding · 数据可靠性与扩展", "WAL|write-ahead log|replication|sharding|预写日志|分片|主从复制", "WAL 在写入数据页前记录恢复所需日志；复制维护多个副本；分片按规则拆分数据。副本不等于独立备份，复制与分片也不是同一机制。", true),
        T("NoSQL / Redis / MongoDB · 非关系存储", "NoSQL|Redis|MongoDB", "NoSQL 泛指多类非传统关系存储；Redis 常用于内存键值数据与缓存，MongoDB 常用文档模型。持久化、事务和一致性保证依产品与配置而定。", true),
        T("ORM / migration · 数据访问与结构迁移", "ORM|schema migration|数据库迁移|对象关系映射", "ORM 在对象模型与关系数据间映射；schema migration 记录并应用结构变化。自动生成查询不保证高效，结构迁移与数据备份也不同。", true),
        T("cache / TTL / eviction · 缓存", "cache|TTL|eviction|缓存|缓存淘汰", "缓存保存可复用结果以降低访问成本；TTL 常表示有效时间，淘汰策略决定空间不足时移除哪些项。过期、主动失效和一致性需另行设计；DNS、IP 等语境中的 TTL 含义还不同。"),
        T("Git · 分布式版本控制", "Git|版本控制", "Git 记录文件快照及其历史，通常在本地完成提交；本地仓库与远端仓库不同，commit 并不等于 push。分支是指向提交的可移动引用。", true),
        T("git commit / add / status · 提交工作流", "git commit|git add|git status", "git add 把指定内容加入暂存区，git commit 从暂存区创建本地提交，git status 查看状态。修改文件后不重新 add，不会自动把最新内容带入同一次普通提交。", true),
        T("git fetch / pull / push · 远端同步", "git fetch|git pull|git push", "fetch 获取远端对象和引用；pull 通常还整合到当前分支，整合方式可为 merge / rebase；push 尝试更新远端引用。拉取不等于只下载。", true),
        T("git merge / rebase · 整合历史", "git merge|git rebase", "merge 合并开发历史；rebase 将提交重放到新基点，通常产生新提交身份。已经共享的历史被重写会影响其他协作者，二者不能简单视为同一操作。", true),
        T("git reset / revert / restore · 恢复与回退", "git reset|git revert|git restore", "reset 可移动引用，并按模式调整暂存区 / 工作区；revert 创建反向提交；restore 恢复指定文件内容。reset --hard 可能丢弃未提交修改，revert 不等于抹去历史。", true),
        T("git branch / switch / checkout · 分支", "git branch|git switch|git checkout|git worktree", "branch 管理分支引用，switch 切换分支；checkout 还包含其他历史用法。worktree 让同一仓库拥有多个检出目录，各目录的当前分支与工作区状态需分别考虑。", true),
        T("Docker / container / image · 容器与镜像", "Docker|container|container image|容器|容器镜像", "镜像是创建运行环境的分层模板，容器是基于镜像启动的隔离进程实例。容器通常共享宿主内核，不是完整虚拟机；持久数据常需要卷或外部存储。", true),
        T("Kubernetes / Pod · 集群编排", "Kubernetes|K8s|kubectl|Pod", "Kubernetes 管理集群中的声明式工作负载；Pod 是共同调度的一组容器及共享环境。Deployment、Service、Ingress 等负责不同层面；Pod 不等于单台虚拟机。", true),
        T("VM / hypervisor · 虚拟机", "virtual machine|hypervisor|虚拟机|虚拟化", "虚拟机在虚拟硬件环境中运行客户操作系统；hypervisor 管理这些环境。与通常共享宿主内核的容器相比，隔离与资源成本的机制不同。", true),
        T("CI/CD / DevOps · 交付流程", "CI/CD|continuous integration|continuous delivery|DevOps|持续集成|持续交付", "持续集成频繁整合并验证代码；持续交付保持可发布状态，持续部署进一步自动上线。流水线通过不等于所有生产条件已被验证。", true),
        T("build / compiler / linker · 构建工具链", "compiler|linker|toolchain|编译器|链接器|工具链", "编译器将源码转换为目标表示，链接器组合目标文件与依赖并解析符号；构建工具组织步骤。编译通过不代表运行时依赖、行为和性能都正确。", true),
        T("ABI / API / SDK · 接口层次", "ABI|API|SDK", "API 是程序可调用的接口；ABI 是二进制层面的调用、布局等约定；SDK 是开发所需工具、库和资料集合。源码 API 兼容不保证二进制 ABI 兼容。", true),
        T("package manager / dependencies · 依赖管理", "package manager|dependency|dependencies|依赖管理|包管理器", "包管理器解析、获取和安装依赖；锁文件固定一次解析的版本与校验信息。依赖版本、平台和运行时条件仍影响可复现构建。"),
        T("debugger / breakpoint / stack trace · 调试", "debugger|breakpoint|stack trace|调试器|断点|堆栈跟踪", "调试器可暂停并检查程序，断点指定停下的位置 / 条件；堆栈跟踪描述调用路径。错误发生的位置不一定就是根因，优化构建还可能改变可见变量和栈形态。", true),
        T("unit / integration / regression test · 软件测试", "unit test|integration test|regression test|单元测试|集成测试|回归测试", "单元测试检查局部行为，集成测试检查组件协作，回归测试防止已知行为被破坏。覆盖率表示执行覆盖的维度，不能单独证明需求正确或没有缺陷。", true),
        T("authentication / authorization · 身份与权限", "authentication|authorization|身份认证|鉴权|授权", "认证回答是谁，授权决定允许做什么。成功登录不代表拥有所有资源权限；服务端需要核验目标资源与操作范围。", true),
        T("hash / encryption / encoding · 摘要、加密与编码", "hash|hashing|encryption|encoding|哈希|散列|加密|编码", "编码改变表示形式，通常无需密钥即可还原；加密用密钥保护机密性；哈希产生摘要，通常不用于还原原文。Base64 不是加密，普通快速哈希也不是合适的密码存储方案。"),
        T("public key / signature · 公钥与数字签名", "public key|private key|digital signature|公钥|私钥|数字签名", "非对称密码使用相关密钥；数字签名以私钥签署、对应公钥验证完整性与来源关系。签名验证成功不等于签名者身份已受信任，私钥应由持有者妥善保护。", true),
        T("OAuth / JWT · 授权与令牌", "OAuth|OAuth2|JWT|JSON Web Token", "OAuth 是授权框架；JWT 是一种带声明的令牌格式，不是完整认证协议。JWT 的签名不等于加密，接受前仍需验证算法、签发方、受众与时效等条件。", true),
        T("XSS / CSRF / SQL injection · 常见漏洞", "XSS|CSRF|SQL injection|SQL注入|跨站脚本|跨站请求伪造", "XSS 使不可信脚本在页面上下文执行；CSRF 借用浏览器凭据触发非预期请求；SQL 注入把数据混成查询语法。输出编码、请求防护和参数化查询分别针对不同问题。", true),
        T("least privilege / sandbox · 权限边界", "least privilege|sandbox|最小权限|沙箱", "最小权限只授予完成任务所需能力；沙箱限制进程可访问的资源和接口。限制范围取决于具体实现，不能只凭名称假定完全隔离。", true),
        T("CPU / core / ISA · 处理器", "CPU|processor|ISA|处理器|指令集", "CPU 执行指令；物理核心、逻辑处理器和指令集是不同层面。线程数量、频率和架构共同影响性能，不能只按一个数字比较。", true),
        T("GPU / VRAM · 并行计算与显存", "GPU|VRAM|显卡|显存", "GPU 擅长大量适合并行的计算；VRAM 保存设备侧数据。显存容量、带宽、计算能力及软件支持各自影响任务能否运行和运行速度。", true),
        T("RAM / ROM / SSD / HDD · 存储层次", "RAM|ROM|SSD|HDD|内存|固态硬盘|机械硬盘", "RAM 通常为易失工作内存；SSD / HDD 提供持久存储，读写与时延特征不同。硬盘容量不能直接替代运行内存，缓存还处在更接近计算单元的层次。", true, caseSensitive: true),
        T("cache line / TLB / NUMA · 硬件局部性", "cache line|TLB|NUMA|缓存行", "缓存行是硬件缓存传输和一致性的常见粒度；TLB 缓存地址转换；NUMA 中访问不同内存节点的延迟可能不同。数据布局与访问局部性会影响性能。", true),
        T("bit / byte / endian · 数据表示", "bit|byte|endianness|big endian|little endian|比特|字节|大端|小端", "比特表示二进制位，现代常见字节为 8 位；大小端描述多字节数据的字节排列。位序、字符编码与字节序不是同一个概念。"),
        T("UTF-8 / Unicode / ASCII · 字符编码", "UTF-8|UTF-16|Unicode|ASCII|字符编码", "Unicode 定义字符码点，UTF-8 / UTF-16 是编码方式；一个用户看到的字符可能包含多个码点。字节数、码点数与屏幕字符数不能混用。", true),
        T("overflow / floating-point precision · 数值误差", "overflow|underflow|floating-point precision|溢出|浮点精度", "整数超范围和浮点舍入是不同问题；其行为依类型、语言和检查模式而定。二进制浮点通常不能精确表示所有十进制小数，比较与累计计算需考虑误差。"),
        T("algorithm / Big O · 算法复杂度", "algorithm|Big O|time complexity|space complexity|算法|时间复杂度|空间复杂度", "算法描述求解步骤；Big O 表示增长率的渐近上界，不是某台机器上的实际毫秒数。应区分最坏、平均、摊还和实际常数开销。", true),
        T("linked list / stack / queue · 线性结构", "linked list|queue|链表|队列|双端队列", "链表通过链接组织节点，随机访问通常需遍历；栈常为后进先出，队列常为先进先出。并发实现、容量限制和具体操作复杂度需看实现。"),
        T("hash table / collision · 哈希表", "hash table|hash map|哈希表|散列表|哈希冲突", "通过哈希将键映射到桶或槽，冲突需额外处理。平均常见访问可很快，但最坏复杂度、扩容和迭代顺序取决于实现。", true),
        T("tree / graph / BFS / DFS · 图与遍历", "binary tree|binary search tree|graph|BFS|DFS|二叉树|图遍历|广度优先|深度优先", "树是受约束的图结构；BFS 按层扩展，DFS 沿路径深入。二叉树不一定是二叉搜索树；BFS 的无权最短路性质不能直接套用任意带权图。", true),
        T("binary search / dynamic programming · 算法方法", "binary search|dynamic programming|二分查找|动态规划", "二分查找依赖有序或可单调判定的区间；动态规划复用子问题状态并按依赖求解。需要先明确状态、边界与转移，不能仅靠术语保证复杂度。", true),
        T("serialization / JSON / YAML · 数据交换", "serialization|deserialization|JSON|YAML|XML|序列化|反序列化", "序列化把数据转换为可存储 / 传输表示，反序列化恢复结构。JSON、YAML、XML 的语法和类型规则不同；解析不可信数据需约束大小、类型与对象构造能力。", true),
        T("distributed system / consensus · 分布式系统", "distributed system|consensus|Raft|Paxos|分布式系统|共识", "多个独立节点通过通信协作，需要处理延迟、部分故障和状态分歧。共识让节点对特定决定达成一致，具体保证依故障模型与协议假设。", true),
        T("CAP / consistency / availability · 分布式权衡", "CAP|eventual consistency|strong consistency|最终一致性|强一致性", "在发生网络分区时，CAP 讨论特定一致性与可用性要求之间的限制；不是日常设计中任意三选二口号。最终一致性还需要系统满足收敛条件。", true, caseSensitive: true),
        T("idempotency / retry / backoff · 重试语义", "idempotency|exponential backoff|幂等|指数退避", "幂等表示同一操作重复执行的预期效果与一次相同；重试需结合去重标识、超时和副作用。指数退避逐步拉长等待，常配合随机抖动。", true),
        T("message queue / Kafka · 消息处理", "message queue|Kafka|RabbitMQ|消息队列", "通过消息缓冲解耦生产者与消费者。投递、确认、重放、顺序和去重保证依配置与处理链路而定，不能只凭队列名称宣称端到端恰好一次。", true),
        T("machine learning / training / inference · 机器学习", "machine learning|deep learning|training|inference|机器学习|深度学习|模型训练|推理", "训练用数据调整模型参数，推理使用已得参数处理输入；深度学习使用多层神经网络。训练表现好不等于对新数据同样可靠。"),
        T("LLM / token / context window · 大语言模型", "LLM|large language model|token|context window|大语言模型|上下文窗口", "LLM 按分词单元处理和生成文本；token 不等于单个汉字或英文单词。上下文窗口限制一次可处理的序列长度，生成结果可能出错，容量也不等于知识准确性。", true),
        T("quantization / GGUF · 本地模型文件", "quantization|GGUF|Q4_K_M|Q4_0|量化", "量化用更低精度表示部分数值，降低模型存储和部分运行成本，同时可能损失质量；GGUF 是常见推理文件格式。位宽、格式兼容性与实际内存需求需分别确认。", true),
        T("embedding / RAG / fine-tuning · 模型应用", "embedding|RAG|fine-tuning|向量嵌入|检索增强|微调", "embedding 将内容表示为向量；RAG 在生成前检索并提供相关材料；微调更新模型参数。检索命中、提示材料和模型输出仍可能出错，三者不是互相等同的操作。", true),
        T("overfitting / gradient / loss · 训练概念", "overfitting|gradient|loss function|过拟合|梯度|损失函数", "损失函数度量训练目标的偏差，梯度描述参数变化对目标的局部影响；过拟合表示对训练数据适应过强而泛化较差。降低训练损失不保证真实任务表现持续改善。", true),
        T("HTML / CSS / DOM · 网页结构与样式", "HTML|CSS|DOM", "HTML 描述文档结构，CSS 控制样式，DOM 是程序操作文档的对象模型。修改 DOM、执行脚本与读取纯文本是不同能力。", true),
        T("framework / library / runtime · 软件组件", "framework|library|runtime|框架|程序库|运行时", "库提供可调用功能，框架常组织应用生命周期，运行时提供执行所需服务。术语边界因生态而异，应用可同时依赖多类组件。"),
        T("regex · 正则表达式", "regex|regexp|regular expression|正则表达式", "描述文本匹配模式；不同引擎对语法、Unicode、回溯和性能保证不同。某些模式在回溯引擎中可能耗时很长，应限制输入和匹配成本。", true)
    };
}
